/// <summary>
/// CB166_SalesOrderSubstitutes
/// Post sales order creation processing multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METSysMessageProcessorTaskService extends SysOperationServiceBase
{    
    boolean isExecutingInBatch, isMainBatchTask;
    SysMessageQueue messageQueue;
    SysMessageRecId messageRecId;
    //SysMessageProcessingState messageProcessingState;
    SysMessageProcessorBatchAffinity            affinity;
    UserConnection                  secondConnection;
    int counter;
    guid topPickingProcessId;

}

Method.Source:
protected void initialise()
{
    secondConnection   = new UserConnection();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPostSalesOrderCreationProcessingContract</c>.
/// </param>
public void process(METSysMessageProcessorContract _contract)
{
    messageQueue = _contract.parmMessageQueue();
    isMainBatchTask    = _contract.parmIsMainBatchTask();
    topPickingProcessId = _contract.parmTopPickingProcessId();

    this.initialise();

    this.processTask(true);

    if (isMainBatchTask)
    {
        //last run of main task thread to make sure all others have been processed
        this.processTask(false);
    }
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{        
    str startStr;
    str startEnd;

    Map logMap = new Map(Types::Int64, Types::Container);

    while (this.getMessageFromQueue(_readPast))
    {
        try
        {              
            if (this.messageRecId)
            {
                startStr = time2Str(DateTimeUtil::time(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone())), TimeSeparator::Colon, TimeFormat::AMPM);
                this.execute(this.messageRecId);
                startEnd = time2Str(DateTimeUtil::time(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone())), TimeSeparator::Colon, TimeFormat::AMPM);
            }

            logMap.insert(this.messageRecId, [startStr, startEnd]);

        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }

    MapEnumerator me = logMap.getEnumerator();
    while (me.moveNext())
    {
        setPrefix(strFmt("Processed message %1", me.currentKey()));
        info(strFmt("Start %1 - End %2", conPeek(me.currentValue(), 1), conPeek(me.currentValue(), 2)));
    }


}

