/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostSalesOrderCreationProcessingQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METPostSalesOrderCreationProcessingContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private SysMessageRecId getMessageFromQueue(boolean _readPast)
{
    METPEPricingTopPickingQueue pricingTopPickingQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    pricingTopPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        /*select firstonly pessimisticlock recid
        from message
            exists join messageProcessingState
        where  messageProcessingState.Message == message.RecId
            && message.MessageQueue == messageQueue
            && messageProcessingState.State == SysMessageState::Queued;

        if (message.RecId)
        {
            this.messageRecId = message.RecId;*/

        select firstonly pessimisticlock MessageRecId
        from pricingTopPickingQueue
        where pricingTopPickingQueue.ProcessId == topPickingProcessId;

        if (pricingTopPickingQueue.MessageRecId)
        {
            this.messageRecId = pricingTopPickingQueue.MessageRecId;
            //counter++;

            /*VNGMessageProcessorDebug table;
            table.Counter = counter;
            table.MessageRecId = messageProcessingState.Message;
            table.insert();*/
            pricingTopPickingQueue.delete();
        }
        else
        {
            // no sales order id found from top picking queue
            this.messageRecId = 0;
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.messageRecId;


}

private SysMessageProcessorMessageLog createLog(SysMessage _message, SysMessageState _nextState)
{
    SysMessageProcessorMessageLog log1 = SysMessageProcessorMessageLog::createLog(_message, _nextState);
    log1.BatchAffinity = affinity;

    return log1;
}

private void executeStateTransition(SysMessage _message, SysMessageState _nextState, boolean _skipTransitionValidation = false)
{
    SysMessageTypeMetadata messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);
    //METPEPricingMessageType messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);

    if (_skipTransitionValidation || messageTypeMetadata.metAllowStateTransition(_message, _nextState))
    {
        SysMessageTarget messageTarget = SysMessageTarget::find(_message.MessageTarget);
        SysMessageTargetInstanceTypeMetadata messageTargetInstanceType = SysMessageTargetInstanceTypeMetadata::construct(messageTarget.InstanceRelationType);
        CompanyId companyId = messageTargetInstanceType.getCompanyId(messageTarget);

        if (companyId)
        {
            changecompany (companyId)
            {
                messageTypeMetadata.processMessageStateTransition(_message, SysMessageStateTransition::newFromStates(_message.messageProcessingState().State, _nextState));
            }
        }
        else
        {
            messageTypeMetadata.processMessageStateTransition(_message, SysMessageStateTransition::newFromStates(_message.messageProcessingState().State, _nextState));
        }
    }
    else
    {
        throw Error(strFmt("@MessageProcessor:Error_RequestedStateTransitionNotAllowed", _message.RecId));
    }
}

private void updateMessageStateToDesiredNextState(int64 _expectedUpdateCount)
{
    SysMessageProcessingState       messageProcessingState;
    SysMessageProcessorMessageLog   messageLog;

    update_recordset messageProcessingState
        setting State = messageLog.NextState
        where messageProcessingState.State == SysMessageState::Queued
        join messageLog
        where messageLog.Message == messageProcessingState.Message
           && (messageLog.Result == SysMessageProcessingResult::Processed || messageLog.Result == SysMessageProcessingResult::Cancelled)
           && messageLog.CreatedTransactionId == appl.curTransactionId();

    if (_expectedUpdateCount != messageProcessingState.RowCount())
    {
        throw Exception::UpdateConflict;
    }
}
